public class TraversalResult { public final boolean success; public final String message,order; public final long steps,timeNanos; private TraversalResult(boolean s,String m,String o,long st,long t){success=s;message=m;order=o;steps=st;timeNanos=t;} public static TraversalResult success(String o,long s,long t){return new TraversalResult(true,"",o,s,t);} public static TraversalResult failure(String m){return new TraversalResult(false,m,"",0,0);} public void display(String n){System.out.println("\n"+n);System.out.println("--------------------------------");if(!success){System.out.println("Error  : "+message);return;}System.out.println("Order  : "+order);System.out.println("Steps  : "+steps);System.out.println("Time   : "+timeNanos+" ns");}}
